#include <vector>
#include <cstddef>
#include <cmath>
#include <stdexcept>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) {
        throw std::invalid_argument("b.size() must equal N");
    }

    const double eps = 1e-12;

    // Build a dense augmented matrix [A | b].
    // To remain correct under every thread count, each thread writes only to rows it owns.
    std::vector<double> aug(N * (N + 1), 0.0);

    // Accumulate COO into dense matrix safely. COO may contain duplicate entries, so use atomic.
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
        const COOElement &e = A[static_cast<size_t>(k)];
        if (e.row >= N || e.column >= N) {
            continue;
        }
        #pragma omp atomic update
        aug[e.row * (N + 1) + e.column] += e.value;
    }

    // Copy b into the augmented column.
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        aug[static_cast<size_t>(i) * (N + 1) + N] = b[static_cast<size_t>(i)];
    }

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Find pivot row (sequential argmax for simplicity and correctness).
        size_t pivot = k;
        double maxAbs = std::fabs(aug[k * (N + 1) + k]);
        for (size_t i = k + 1; i < N; ++i) {
            const double v = std::fabs(aug[i * (N + 1) + k]);
            if (v > maxAbs) {
                maxAbs = v;
                pivot = i;
            }
        }

        if (maxAbs < eps) {
            throw std::runtime_error("Matrix is singular or nearly singular");
        }

        // Swap pivot row into place.
        if (pivot != k) {
            for (size_t j = k; j <= N; ++j) {
                std::swap(aug[k * (N + 1) + j], aug[pivot * (N + 1) + j]);
            }
        }

        const double pivotVal = aug[k * (N + 1) + k];

        // Eliminate rows below pivot in parallel.
        // Each iteration updates a distinct row i, so there are no conflicting writes.
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            const double factor = aug[i * (N + 1) + k] / pivotVal;
            aug[i * (N + 1) + k] = 0.0;
            for (size_t j = k + 1; j <= N; ++j) {
                aug[i * (N + 1) + j] -= factor * aug[k * (N + 1) + j];
            }
        }
    }

    x.assign(N, 0.0);

    // Back substitution (sequential due to dependency chain).
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        const size_t i = static_cast<size_t>(ii);
        double sum = aug[i * (N + 1) + N];
        for (size_t j = i + 1; j < N; ++j) {
            sum -= aug[i * (N + 1) + j] * x[j];
        }

        const double diag = aug[i * (N + 1) + i];
        if (std::fabs(diag) < eps) {
            throw std::runtime_error("Matrix is singular or nearly singular");
        }
        x[i] = sum / diag;
    }
}
